'use strict';
let wordPlayDisplay={ink:'syllables',choices:2};
try{const v=JSON.parse(localStorage.getItem('spotmatch-word-play-v1')||'null');if(v&&['syllables','letters','plain'].includes(v.ink))wordPlayDisplay.ink=v.ink;if(v&&[2,3].includes(v.choices))wordPlayDisplay.choices=v.choices;}catch{}
const wordPlayInk={b:'#244f91',d:'#9c431c',p:'#19635a',g:'#663d8b'};
function wordPlayActive(){return !!readingState&&!!readingGame(readingState.id)?.wordPlay;}
function wordPlayPaint(word){const chunks=wordPlaySyllables[word]||[word],esc=readingEscape;if(wordPlayDisplay.ink==='plain')return `<span class="wp-word" aria-label="${esc(word)}">${esc(word)}</span>`;if(wordPlayDisplay.ink==='letters')return `<span class="wp-word" aria-label="${esc(word)}">${[...word].map(c=>`<span style="color:${wordPlayInk[c]||'#263f37'}">${esc(c)}</span>`).join('')}</span>`;return `<span class="wp-word wp-syllables" aria-label="${esc(word)}">${chunks.map((c,i)=>`<span class="wp-syllable wp-beat-${i%2}">${esc(c)}</span>`).join('')}</span>`;}
function wordPlayChunkPaint(chunk){const i=wordPlaySyllables[readingState.item].indexOf(chunk);if(wordPlayDisplay.ink!=='syllables')return wordPlayPaint(chunk);return `<span class="wp-word wp-syllables"><span class="wp-syllable wp-beat-${i%2}">${readingEscape(chunk)}</span></span>`;}
function wordPlayPicture(word){return readingPicture(readingWord(word)?.picture||word);}
function wordPlayOrder(list,salt=0){const n=(readingState.round+readingState.seed+salt)%list.length;return list.slice(n).concat(list.slice(0,n));}
function wordPlayOptions(answer,pool=['cup','hat','bed','mop','pig','bag']){return wordPlayOrder([answer,...pool.filter(w=>w!==answer&&!([answer,w].includes('mug')&&[answer,w].includes('cup'))&&!([answer,w].includes('hat')&&[answer,w].includes('cap'))).slice(0,(readingState.wp?.choices||wordPlayDisplay.choices)-1)],1+(readingState.wp?.link||0));}
function wordPlayPrepare(){if(!wordPlayActive())return false;const s=readingState,g=readingGame(s.id);s.word=null;s.wp={choices:wordPlayDisplay.choices,selected:null,loaded:[],link:0,slots:[null,null],phase:'build',labels:[],version:0};if(g.mode==='word-stickers'){const words=s.item.split('|').slice(0,wordPlayDisplay.choices);s.wp.labels=words.slice(1).concat(words[0]);}wordQuestPrepare();return true;}
function wordPlayCue(){return wordPlayActive()?readingGame(readingState.id).adult+' Read the print before using pictures to check meaning. A match may use adult help, memory or elimination; it is not a reading assessment.':null;}
function wordPlayControls(){if(!wordPlayActive())return null;return `<details class="wp-settings"><summary>${wordPlayDisplay.ink==='syllables'?'Syllable colours':wordPlayDisplay.ink==='letters'?'Letter cues':'Plain print'} · game settings</summary><label>Word display <select id="wpInk"><option value="syllables" ${wordPlayDisplay.ink==='syllables'?'selected':''}>Syllable colours</option><option value="letters" ${wordPlayDisplay.ink==='letters'?'selected':''}>b, d, p, g letter cues</option><option value="plain" ${wordPlayDisplay.ink==='plain'?'selected':''}>Plain print</option></select></label><label>Picture choices <select id="wpChoices"><option value="2" ${wordPlayDisplay.choices===2?'selected':''}>Two · quieter board</option><option value="3" ${wordPlayDisplay.choices===3?'selected':''}>Three · more variety</option></select></label><p>Untimed. Tap or keyboard works everywhere; dragging is optional. Choice changes apply to the next challenge in picture-choice games and the label album. Other puzzles keep their small fixed boards; the trolley has two list items and four cargo cards. Display changes keep your work.</p>${wordPlayDisplay.ink==='letters'?`<div class="wp-letter-guide">${['b','d','p','g'].map(c=>`<span style="color:${wordPlayInk[c]}">${c}</span>`).join('')}<small>Compare the whole shape: d reaches up; p and g reach below. g can have different forms in other fonts. Colour is only a reminder.</small></div>`:'<p>One spoken syllable gets one colour. Underlines also mark the chunks. Colours are optional prompts, not a treatment.</p>'}</details>`;}
function wordPlayCard(word,attr,extra=''){return `<button class="wp-picture ${extra}" ${attr} aria-label="Picture: ${readingEscape(word)}">${wordPlayPicture(word)}</button>`;}
function wordPlayChallenge(){const quest=wordQuestChallenge();if(quest!==null)return quest;if(!wordPlayActive())return null;const s=readingState,g=readingGame(s.id),w=s.wp,mode=g.mode;let heading='',body='';
 if(mode==='word-fishing'){heading='Read the word. Catch its picture-fish!';body=`<div class="wp-ticket">${wordPlayPaint(s.item)}</div><div class="wp-pond">${wordPlayOptions(s.item).map(x=>`<button class="wp-fish" data-wp-fish="${x}" aria-label="Catch picture: ${x}"><span class="wp-fish-eye" aria-hidden="true">●</span><span class="wp-fish-badge">${wordPlayPicture(x)}</span><span class="wp-fish-tail" aria-hidden="true">◀</span></button>`).join('')}</div><button id="wpNet" class="wp-net" aria-label="Select the net; then choose a picture fish" aria-pressed="${w.selected==='net'}">${readingPicture('net')}<span>Drag the net to a fish, or tap a fish.</span></button>`;}
 else if(mode==='word-trolley'){const list=s.item.split('|'),pool=wordPlayOrder([...list,...['rug','bed','hat','cap','mop','pig'].filter(x=>!list.includes(x)&&!list.some(t=>[x,t].includes('cap')&&[x,t].includes('hat')||[x,t].includes('cup')&&[x,t].includes('mug'))).slice(0,2)]);heading='Read the list. Pack both picture cards!';body=`<div class="wp-list">${list.map(x=>`<span class="${w.loaded.includes(x)?'wp-ticked':''}">${w.loaded.includes(x)?'<i aria-label="packed">✓</i>':''}${wordPlayPaint(x)}</span>`).join('')}</div><div class="wp-shelf">${pool.filter(x=>!w.loaded.includes(x)).map(x=>wordPlayCard(x,`data-wp-cargo="${x}" aria-pressed="${w.selected===x}"`)).join('')}</div><button id="wpTrolley" class="wp-trolley" aria-label="Load selected picture into trolley"><span class="wp-load">${w.loaded.map(x=>`<span>${wordPlayPicture(x)}</span>`).join('')||'<span class="wp-empty">Your picture-card trolley</span>'}</span><span class="wp-wheels" aria-hidden="true">●　　　　　　　 ●</span></button><p>Drag cards into the trolley, or tap a card then the trolley. Packed cards stay inside.</p>`;}
 else if(mode==='word-stickers'){const words=s.item.split('|').slice(0,w.labels.length);heading='Robot mixed the labels. Swap them to fix the album!';body=`<div class="wp-album">${words.map((x,i)=>`<div class="wp-album-page"><div class="wp-album-picture">${wordPlayPicture(x)}</div><button class="wp-label" data-wp-label="${i}" aria-label="Move label ${w.labels[i]}" aria-pressed="${w.selected===i}">${wordPlayPaint(w.labels[i])}</button></div>`).join('')}</div><p>Drag a label onto another label, or tap two labels to swap. Every label needs to fit its picture.</p>`;}
 else if(mode==='word-dominoes'){const trail=s.item.split('|'),target=trail[w.link];heading='Read the trail word. Join the matching picture domino!';body=`<div class="wp-path">${trail.slice(0,w.link).map((x,i)=>`<span class="wp-laid">${wordPlayPicture(x)}${wordPlayPaint(trail[i+1]||x)}</span>`).join('')}<button id="wpPath" class="wp-path-end" aria-label="Connect selected domino here">${wordPlayPaint(target)}<span>＋</span></button></div><div class="wp-dominoes">${wordPlayOptions(target).map(x=>`<button class="wp-domino" data-wp-domino="${x}" aria-label="Domino picture: ${x}" aria-pressed="${w.selected===x}"><span>${wordPlayPicture(x)}</span><span>${x===target?(trail[w.link+1]?wordPlayPaint(trail[w.link+1]):'<b class="wp-flag" aria-label="Finish flag">⚑</b>'):wordPlayPaint(x==='cup'?'hat':'cup')}</span></button>`).join('')}</div><p>Drag a domino to the word, or tap a domino then the word. Three links reach the flag.</p>`;}
 else if(mode==='word-syllables'){heading=w.phase==='build'?'Build the two-beat word train.':'Read your word. Deliver it to its picture!';const chunks=wordPlaySyllables[s.item];if(w.phase==='build'){const bank=wordPlayOrder(chunks,1);body=`<p class="wp-model">Word model: ${wordPlayPaint(s.item)}</p><div class="wp-train"><span class="wp-engine" aria-hidden="true">🚂</span>${w.slots.map((x,i)=>`<button class="wp-carriage" data-wp-slot="${i}" aria-label="Syllable carriage ${i+1}${x===null?', empty':', '+bank[x]}">${x===null?i+1:wordPlayChunkPaint(bank[x])}</button>`).join('')}</div><div class="wp-chunks">${bank.map((x,i)=>`<button data-wp-chunk="${i}" class="wp-chunk" ${w.slots.includes(i)?'disabled':''}>${wordPlayChunkPaint(x)}</button>`).join('')}</div><p>Drag each chunk to a carriage, or tap to fill the next space. Tap a filled carriage to return it; drag filled carriages to swap.</p>`;}else body=`<div class="wp-ticket">${wordPlayPaint(s.item)}</div><div class="wp-picture-options">${wordPlayOptions(s.item,['napkin','basket','helmet','mitten']).map(x=>wordPlayCard(x,`data-wp-meaning="${x}"`)).join('')}</div>`;}
 return `<div class="wp-board wp-${mode}"><h2 class="reading-invitation" tabindex="-1">${heading}</h2>${body}</div>`;
}
function wordPlayFocusKey(el){if(!el||!wordPlayActive())return null;if(el.id?.startsWith('wq'))return '#'+el.id;for(const a of [...el.attributes||[]])if(a.name.startsWith('data-wq-'))return '['+a.name+'="'+a.value+'"]';if(el.id?.startsWith('wp'))return '#'+el.id;for(const key of ['fish','cargo','label','domino','slot','chunk','meaning'])if(el.hasAttribute('data-wp-'+key))return '[data-wp-'+key+'="'+el.getAttribute('data-wp-'+key)+'"]';return null;}
function wordPlayRestoreFocus(key){if(!wordPlayActive())return;const w=readingState.wp;let target=readingState.done?'.reading-result':key;if(key.startsWith('[data-wq-letter')&&w.picked!==null)target='[data-wq-change-slot]';if(key.startsWith('[data-wq-bank')&&w.picked!==null)target='[data-wq-cell]';if(key.startsWith('[data-wq-sort')&&w.picked)target='[data-wq-bin]';if(key.startsWith('[data-wq-food')&&w.picked)target='[data-wq-recipe-slot="'+w.placed.length+'"]';if(key.startsWith('[data-wq-paint')&&w.picked)target='#wqCanvas';if(key.startsWith('[data-wq-missing')&&w.picked)target='#wqMissing';if(key.startsWith('[data-wp-cargo')&&w.selected)target='#wpTrolley';if(key.startsWith('[data-wp-domino')&&w.selected)target='#wpPath';if(key.startsWith('[data-wp-chunk')&&w.phase==='meaning')target='[data-wp-meaning]';const el=app.querySelector(target);if(el&&!el.disabled)el.focus({preventScroll:true});else app.querySelector('.reading-invitation')?.focus({preventScroll:true});}
function wordPlayRender(){readingState.wp.version++;readingRender();}
function wordPlayCatch(word){if(!readingCanAct()||!wordPlayActive())return;if(word!==readingState.item)return readingWrong('That fish stays in the pond. Read the whole word together, then try another picture.');readingSuccess('meaning');}
function wordPlayLoad(word){if(!readingCanAct()||!wordPlayActive())return;const s=readingState,w=s.wp;if(!s.item.split('|').includes(word))return readingWrong('That card is not on this delivery list. Read one list word together.');if(w.loaded.includes(word))return;w.loaded.push(word);w.selected=null;if(w.loaded.length===2)readingSuccess('meaning');else{s.message='Packed! One more word on the list.';wordPlayRender();}}
function wordPlaySwap(a,b){if(!readingCanAct()||!wordPlayActive())return;const s=readingState,w=s.wp;if(!Number.isInteger(a)||!Number.isInteger(b)||a===b||!w.labels[a]||!w.labels[b])return;[w.labels[a],w.labels[b]]=[w.labels[b],w.labels[a]];w.selected=null;if(w.labels.join('|')===s.item.split('|').slice(0,w.labels.length).join('|'))readingSuccess('meaning');else{s.message='Labels swapped. Read them again: which picture still needs its label?';wordPlayRender();}}
function wordPlayJoin(word){if(!readingCanAct()||!wordPlayActive())return;const s=readingState,w=s.wp;if(word!==s.item.split('|')[w.link])return readingWrong('That picture does not fit this word yet. Read across all the spellings together.');w.link++;w.selected=null;if(w.link===3)readingSuccess('meaning');else{s.message='Connected! Read the new word at the end.';wordPlayRender();}}
function wordPlayChunk(index,slot){if(!readingCanAct()||!wordPlayActive())return;const s=readingState,w=s.wp,bank=wordPlayOrder(wordPlaySyllables[s.item],1);if(w.phase!=='build'||!Number.isInteger(index)||!bank[index]||w.slots.includes(index))return;const at=slot===undefined?w.slots.indexOf(null):slot;if(![0,1].includes(at))return;w.slots[at]=index;wordPlayCheckChunks();}
function wordPlayCheckChunks(){const s=readingState,w=s.wp,bank=wordPlayOrder(wordPlaySyllables[s.item],1);if(w.slots.every(i=>i!==null)){if(w.slots.map(i=>bank[i]).join('')===s.item){w.phase='meaning';s.message='The train is built! Read both chunks together and find its picture.';}else s.message='The chunks need a swap. Compare the word model; tap a carriage to return its chunk.';}wordPlayRender();}
function wordPlayMeaning(word){if(!readingCanAct()||!wordPlayActive()||readingState.wp.phase!=='meaning')return;if(word!==readingState.item)return readingWrong('Read the two chunks together again, then check the picture.');readingSuccess('meaning');}
function wordPlayResult(){const quest=wordQuestResult();if(quest!==null)return quest;if(!wordPlayActive())return null;const s=readingState,mode=readingGame(s.id).mode,words=s.item.split('|');return `<div class="wp-result">${words.map(x=>`<span>${wordPlayPicture(x)}${wordPlayPaint(x)}</span>`).join('')}<b aria-hidden="true">${mode==='word-dominoes'?'⚑':'★'}</b></div>`;}
function wordPlayMessage(){const quest=wordQuestMessage();if(quest!==null)return quest;if(!wordPlayActive())return null;return {'word-fishing':'Great catch! The word and picture belong together.','word-trolley':'Delivery ready! Both picture cards are packed.','word-stickers':'Lovely repair! Every label fits its picture.','word-dominoes':'You reached the flag! Three words made the trail.','word-syllables':'All aboard! You built a word and found its picture.'}[readingGame(readingState.id).mode];}
function wordPlayBind(){if(!wordPlayActive())return;const s=readingState,w=s.wp,round=s.round,version=++w.version,qa=sel=>[...app.querySelectorAll(sel)],q=sel=>app.querySelector(sel),valid=()=>readingState===s&&s.round===round&&s.wp===w&&w.version===version&&readingCanAct();const bind=(sel,targets,drop)=>qa(sel).forEach(el=>{if(typeof TouchPlay!=='undefined')TouchPlay.bind(el,{targets:()=>qa(targets),drop:t=>{if(valid()&&t)drop(el,t);}});});
 q('#wpInk').onchange=e=>{wordPlayDisplay.ink=e.target.value;s.help=true;try{localStorage.setItem('spotmatch-word-play-v1',JSON.stringify(wordPlayDisplay));}catch{}wordPlayRender();q('#wpInk')?.focus();};q('#wpChoices').onchange=e=>{wordPlayDisplay.choices=+e.target.value;s.help=true;try{localStorage.setItem('spotmatch-word-play-v1',JSON.stringify(wordPlayDisplay));}catch{}s.message='Choice setting saved for the next challenge.';wordPlayRender();};
 if(!readingCanAct())return;if(wordQuestGame()){wordQuestBind();return;}qa('[data-wp-fish]').forEach(el=>el.onclick=()=>wordPlayCatch(el.dataset.wpFish));q('#wpNet')?.addEventListener('click',()=>{w.selected=w.selected==='net'?null:'net';wordPlayRender();});bind('#wpNet','[data-wp-fish]',(el,t)=>wordPlayCatch(t.dataset.wpFish));bind('[data-wp-fish]','#wpNet',el=>wordPlayCatch(el.dataset.wpFish));
 qa('[data-wp-cargo]').forEach(el=>el.onclick=()=>{w.selected=el.dataset.wpCargo;wordPlayRender();});q('#wpTrolley')?.addEventListener('click',()=>{if(w.selected)wordPlayLoad(w.selected);else readingWrong('Choose a picture card, then tap the trolley.');});bind('[data-wp-cargo]','#wpTrolley',el=>wordPlayLoad(el.dataset.wpCargo));
 qa('[data-wp-label]').forEach(el=>el.onclick=()=>{const i=+el.dataset.wpLabel;if(w.selected===null){w.selected=i;wordPlayRender();}else if(w.selected===i){w.selected=null;wordPlayRender();}else wordPlaySwap(w.selected,i);});bind('[data-wp-label]','[data-wp-label]',(el,t)=>wordPlaySwap(+el.dataset.wpLabel,+t.dataset.wpLabel));
 qa('[data-wp-domino]').forEach(el=>el.onclick=()=>{w.selected=el.dataset.wpDomino;wordPlayRender();});q('#wpPath')?.addEventListener('click',()=>{if(w.selected)wordPlayJoin(w.selected);else readingWrong('Choose a picture domino, then tap the word at the end of the path.');});bind('[data-wp-domino]','#wpPath',el=>wordPlayJoin(el.dataset.wpDomino));
 qa('[data-wp-chunk]').forEach(el=>el.onclick=()=>wordPlayChunk(+el.dataset.wpChunk));qa('[data-wp-slot]').forEach(el=>el.onclick=()=>{w.slots[+el.dataset.wpSlot]=null;s.message='';wordPlayRender();});bind('[data-wp-chunk]:not(:disabled)','[data-wp-slot]',(el,t)=>wordPlayChunk(+el.dataset.wpChunk,+t.dataset.wpSlot));bind('[data-wp-slot]','[data-wp-slot]',(el,t)=>{const a=+el.dataset.wpSlot,b=+t.dataset.wpSlot;if(a!==b&&w.slots[a]!==null){[w.slots[a],w.slots[b]]=[w.slots[b],w.slots[a]];wordPlayCheckChunks();}});qa('[data-wp-meaning]').forEach(el=>el.onclick=()=>wordPlayMeaning(el.dataset.wpMeaning));bind('[data-wp-meaning]','.wp-ticket',el=>wordPlayMeaning(el.dataset.wpMeaning));
}
